const special=(id,c,en,pt,enD,ptD,icon)=>add(id,c,'special',en,pt,enD,ptD,{[id]:true},icon),mark=(id,c,en,pt,enD,ptD,icon)=>add(id,c,'milestone',en,pt,enD,ptD,{[id]:true},icon);
special('first_impact','power','First Impact','Primeiro impacto','Each unit’s first basic attack each round deals 35% more damage and stuns its target for 0.3s.','O primeiro ataque básico de cada unidade na rodada causa +35% de dano e atordoa o alvo por 0,3s.');
special('execution','power','Execution','Execução','Deal 20% more damage to enemies below 30% health. Defeating an enemy grants 20% special charge.','Causa +20% de dano em inimigos abaixo de 30% de vida. Derrotar um inimigo concede 20% da barra de especial.');
special('penetration','power','Penetration','Penetração','Basic attacks ignore 10% of the target’s defense; critical hits ignore 25%.','Ataques básicos ignoram 10% da defesa do alvo; acertos críticos ignoram 25%.');
mark('devastating','power','Devastating Opening','Abertura devastadora','Each unit’s first offensive skill each round deals 45% more damage and leaves its targets Exposed (+12% damage taken) for 3s.','A primeira skill ofensiva de cada unidade na rodada causa +45% de dano e deixa os alvos Expostos (+12% de dano recebido) por 3s.');
special('urgent_heal','vitality','Urgent Recovery','Recuperação urgente','The first time each round a unit falls below 40% health, it recovers 6% maximum health over 3s.','A primeira vez na rodada em que uma unidade cai abaixo de 40% de vida, ela recupera 6% da vida máxima em 3s.');
special('second_wind','vitality','Second Wind','Segundo fôlego','Each unit’s first skill each round heals it and the most wounded ally for 4% maximum health.','A primeira skill de cada unidade na rodada cura ela e o aliado mais ferido em 4% da vida máxima.');
